// Works out which expected invoices have not arrived, and what to do about each
// one. Nothing here sends anything. It reads three tabs and returns one row per
// action, so every rule that decides whether a supplier gets an email is in one
// place you can read and change.

const register = $('Expected invoices').all().map(i => i.json);
const received = $('Invoices received').all().map(i => i.json);
const chases   = $('Chase log').all().map(i => i.json);

// ---- tunables ---------------------------------------------------------------
const LOOKBACK_PERIODS = 3;   // how far back to care. Stops a first run chasing years
const GRACE_DAYS       = 3;   // days after the due date before anything is late
const REMINDER_GAP     = 5;   // days to wait between one chase and the next
const MAX_ATTEMPTS     = 2;   // reminders before it goes to a person
const MAX_PER_RUN      = 20;  // hard ceiling on actions in a single run
// -----------------------------------------------------------------------------

const norm = s => String(s == null ? '' : s).toLowerCase()
  .replace(/\b(ltd|limited|llc|l\.l\.c|plc|llp|inc|co|company|fzco|fze|fzc|est|establishment)\b/g, '')
  .replace(/[^a-z0-9]/g, '').trim();

const clean = v => String(v == null ? '' : v).trim();

const parseDate = v => {
  const s = clean(v);
  if (!s) return null;
  const t = Date.parse(s);
  return Number.isFinite(t) ? new Date(t) : null;
};

const daysBetween = (a, b) => Math.floor((a.getTime() - b.getTime()) / 86400000);

const today = new Date();
today.setHours(0, 0, 0, 0);

// Period keys. A period is what an invoice covers, not when it arrived, so a
// September invoice that turns up in October still closes September.
const monthKey   = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
const quarterKey = d => d.getFullYear() + '-Q' + (Math.floor(d.getMonth() / 3) + 1);
const weekKey = function (d) {
  const x = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const day = x.getUTCDay() || 7;
  x.setUTCDate(x.getUTCDate() + 4 - day);
  const start = new Date(Date.UTC(x.getUTCFullYear(), 0, 1));
  const week = Math.ceil(((x - start) / 86400000 + 1) / 7);
  return x.getUTCFullYear() + '-W' + String(week).padStart(2, '0');
};

// The periods to look at, newest first, and the day each one's invoice is due.
function periodsFor(cadence, dueDay) {
  const out = [];
  if (cadence === 'monthly') {
    for (let i = 0; i < LOOKBACK_PERIODS; i++) {
      const d = new Date(today.getFullYear(), today.getMonth() - i, 1);
      const lastDay = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
      // The invoice for a month is due in the month AFTER it, on dueDay.
      const due = new Date(d.getFullYear(), d.getMonth() + 1, Math.min(dueDay, lastDay));
      out.push({ key: monthKey(d), due, label: 'the ' + monthKey(d) + ' invoice' });
    }
  } else if (cadence === 'quarterly') {
    for (let i = 0; i < LOOKBACK_PERIODS; i++) {
      const d = new Date(today.getFullYear(), today.getMonth() - (i * 3), 1);
      const qStart = new Date(d.getFullYear(), Math.floor(d.getMonth() / 3) * 3, 1);
      const due = new Date(qStart.getFullYear(), qStart.getMonth() + 3, Math.min(dueDay, 28));
      out.push({ key: quarterKey(qStart), due, label: 'the ' + quarterKey(qStart) + ' invoice' });
    }
  } else if (cadence === 'weekly') {
    for (let i = 0; i < LOOKBACK_PERIODS; i++) {
      const d = new Date(today.getTime() - i * 7 * 86400000);
      const due = new Date(d.getTime() + 7 * 86400000);
      out.push({ key: weekKey(d), due, label: 'the week ' + weekKey(d) + ' invoice' });
    }
  }
  return out;
}

const actions = [];
const problems = [];

// Index what has arrived and what has already been chased, by normalised
// supplier. A loose name match here would close the wrong supplier's chase or
// chase one that has already paid, so the key is exact after normalising.
const receivedKeys = new Set();
received.forEach(function (r) {
  const k = norm(r.supplier);
  const p = clean(r.period);
  if (k && p) receivedKeys.add(k + '|' + p);
});

const chaseIndex = {};
chases.forEach(function (c) {
  const k = norm(c.supplier);
  const p = clean(c.period);
  if (!k || !p) return;
  const id = k + '|' + p;
  if (!chaseIndex[id]) chaseIndex[id] = { attempts: 0, escalated: false, last: null };
  const entry = chaseIndex[id];
  const action = clean(c.action).toLowerCase();
  if (action === 'escalated') entry.escalated = true;
  else entry.attempts += 1;
  const when = parseDate(c.sent_at);
  if (when && (!entry.last || when > entry.last)) entry.last = when;
});

// Group the register by the name we will match received rows against. Two rows
// that are the same supplier typed twice get chased once, not twice. Two rows
// that are genuinely different suppliers but collapse to the same key once
// punctuation and "Ltd" style endings are removed cannot be told apart later,
// so neither is chased and the clash is reported. Guessing there would either
// chase a supplier who has already invoiced or leave a real one unchased.
const groups = {};
register.forEach(function (row) {
  const supplier = clean(row.supplier);
  if (!supplier) return;   // a blank row from the sheet, not a configuration fault
  const k = norm(supplier);
  if (!k) return;
  if (!groups[k]) groups[k] = { rows: [], names: [] };
  groups[k].rows.push(row);
  if (groups[k].names.indexOf(supplier) === -1) groups[k].names.push(supplier);
});

Object.keys(groups).forEach(function (groupKey) {
  const group = groups[groupKey];
  if (group.names.length > 1) {
    problems.push('these register rows cannot be told apart once punctuation and endings like Ltd are removed, so neither is chased: ' + group.names.join(' and '));
    return;
  }
  const row = group.rows[0];
  const supplier = clean(row.supplier);

  const status = (clean(row.status) || 'active').toLowerCase();
  if (status !== 'active') return;

  const cadence = clean(row.cadence).toLowerCase();
  if (['monthly', 'quarterly', 'weekly'].indexOf(cadence) === -1) {
    problems.push(supplier + ': cadence reads "' + clean(row.cadence) + '", which is not monthly, quarterly or weekly');
    return;
  }

  const dueDay = parseInt(clean(row.due_day), 10);
  if (!Number.isFinite(dueDay) || dueDay < 1 || dueDay > 31) {
    problems.push(supplier + ': due day reads "' + clean(row.due_day) + '", which is not a day of the month');
    return;
  }

  const grace = Number.isFinite(parseInt(clean(row.grace_days), 10)) ? parseInt(clean(row.grace_days), 10) : GRACE_DAYS;
  const key = groupKey;
  const email = clean(row.email);
  const emailLooksReal = email.indexOf('@') > 0 && email.indexOf('.', email.indexOf('@')) > 0;

  periodsFor(cadence, dueDay).forEach(function (period) {
    const id = key + '|' + period.key;

    if (receivedKeys.has(id)) return;                    // it arrived
    if (daysBetween(today, period.due) < grace) return;  // not late yet, and never chase a future period

    const state = chaseIndex[id] || { attempts: 0, escalated: false, last: null };
    if (state.escalated) return;                         // a person has it, stop chasing

    const daysSinceLast = state.last ? daysBetween(today, state.last) : null;

    // No usable address is not a reason to do nothing. It goes straight to a
    // person, once, with the reason on it.
    if (!emailLooksReal) {
      if (state.attempts === 0) {
        actions.push(build(row, period, 'escalated', 1, 'no usable email address on the register'));
      }
      return;
    }

    if (state.attempts === 0) {
      actions.push(build(row, period, 'first reminder', 1, ''));
    } else if (daysSinceLast !== null && daysSinceLast < REMINDER_GAP) {
      return;                                            // still inside the gap, leave it alone
    } else if (state.attempts < MAX_ATTEMPTS) {
      actions.push(build(row, period, 'second reminder', state.attempts + 1, ''));
    } else {
      actions.push(build(row, period, 'escalated', state.attempts + 1,
        'chased ' + state.attempts + ' times with no invoice'));
    }
  });
});

function build(row, period, action, attempt, reason) {
  const daysLate = daysBetween(today, period.due);
  return {
    supplier: clean(row.supplier),
    email: clean(row.email),
    period: period.key,
    period_label: period.label,
    due_date: period.due.toISOString().slice(0, 10),
    days_late: daysLate,
    action: action,
    attempt: attempt,
    reason: reason,
    reference: clean(row.reference),
    escalate_to: clean(row.escalate_to),
    cadence: clean(row.cadence).toLowerCase(),
    checked_at: new Date().toISOString(),
  };
}

// Oldest first, because the invoice that has been missing longest is the one
// that matters, and a run that hits the ceiling should spend it on those.
actions.sort(function (a, b) { return b.days_late - a.days_late; });

const capped = actions.slice(0, MAX_PER_RUN);
const heldBack = actions.length - capped.length;

const out = capped.map(function (a, i) {
  a.configuration_problems = i === 0 ? problems.join('; ') : '';
  a.held_back = i === 0 ? heldBack : 0;
  return { json: a };
});

// A broken register stops invoices being chased, so it is reported on its own
// item rather than riding along on a chase that may not exist. It is reported
// every run until it is fixed, because silence would look like everything is
// in order.
if (problems.length) {
  out.push({ json: {
    action: 'configuration problem',
    supplier: '', period: '', period_label: '', email: '', due_date: '',
    days_late: 0, attempt: 0, reason: problems.join('; '),
    configuration_problems: problems.join('; '),
    held_back: heldBack, checked_at: new Date().toISOString(),
  } });
}

if (!out.length) {
  return [{ json: { action: 'nothing to chase', supplier: '', period: '', configuration_problems: '', held_back: 0 } }];
}

return out;

