parameters.jsCode:
// Ties an invoice that has arrived to a row on the register, and works out
// which period it closes. Nothing is written from here. A wrong match is worse
// than no match, because it silently stops a chase for an invoice that never
// came, so anything ambiguous is handed to a person instead of guessed.

const doc = $('Read who it is from').first().json.output || $('Read who it is from').first().json;
const register = $('Expected invoices for matching').all().map(i => i.json);

const norm = s => String(s == null ? '' : s).toLowerCase()
  .replace(/\b(ltd|limited|llc|l\.l\.c|plc|llp|inc|co|company|fzco|fze|fzc|est|establishment)\b/g, '')
  .replace(/[^a-z0-9]/g, '').trim();

const clean = v => String(v == null ? '' : v).trim();

const parseDate = v => {
  const s = clean(v);
  if (!s) return null;
  const t = Date.parse(s);
  return Number.isFinite(t) ? new Date(t) : null;
};

const monthKey   = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
const quarterKey = d => d.getFullYear() + '-Q' + (Math.floor(d.getMonth() / 3) + 1);
const weekKey = function (d) {
  const x = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const day = x.getUTCDay() || 7;
  x.setUTCDate(x.getUTCDate() + 4 - day);
  const start = new Date(Date.UTC(x.getUTCFullYear(), 0, 1));
  const week = Math.ceil(((x - start) / 86400000 + 1) / 7);
  return x.getUTCFullYear() + '-W' + String(week).padStart(2, '0');
};

function fail(reason) {
  return [{ json: {
    matched: false,
    reason: reason,
    read_supplier: clean(doc.supplier),
    invoice_number: clean(doc.invoice_number),
    issue_date: clean(doc.issue_date),
    period: '',
    supplier: '',
    period_inferred: false,
    received_at: new Date().toISOString(),
  } }];
}

const readSupplier = clean(doc.supplier);
if (!readSupplier) return fail('the supplier could not be read off the invoice');

const key = norm(readSupplier);

// Exact on the normalised name first. A near match is accepted only when it is
// the only one, and only when the name is long enough for "contains" to mean
// anything. This is the same rule the posting workflow uses, and for the same
// reason: two suppliers with similar names must never be treated as one.
let row = null;
const exact = register.filter(r => norm(r.supplier) === key);
if (exact.length === 1) {
  row = exact[0];
} else if (exact.length > 1) {
  return fail('"' + readSupplier + '" matches ' + exact.length + ' rows on the register, so a person picks the right one');
} else if (key.length >= 5) {
  const near = register.filter(function (r) {
    const k = norm(r.supplier);
    return k.length >= 5 && (k.indexOf(key) !== -1 || key.indexOf(k) !== -1);
  });
  if (near.length === 1) row = near[0];
  else if (near.length > 1) return fail('"' + readSupplier + '" is close to ' + near.length + ' rows on the register, so a person picks the right one');
}

if (!row) return fail('"' + readSupplier + '" is not on the expected invoice register');

const cadence = clean(row.cadence).toLowerCase();
if (['monthly', 'quarterly', 'weekly'].indexOf(cadence) === -1) {
  return fail('the register row for "' + clean(row.supplier) + '" has cadence "' + clean(row.cadence) + '", which is not monthly, quarterly or weekly');
}

// Which period does this invoice close. An invoice that states the period it
// covers is believed. Otherwise the register's billing convention decides, and
// the row is marked inferred so a person can see it was not read off the paper.
const periodEnd = parseDate(doc.period_end);
const issued = parseDate(doc.issue_date);
let basis = periodEnd;
let inferred = false;

if (!basis) {
  if (!issued) return fail('neither a period nor a readable issue date is on the invoice');
  inferred = true;
  const billing = (clean(row.billing) || 'arrears').toLowerCase();
  if (billing === 'advance') {
    basis = issued;
  } else if (cadence === 'monthly') {
    basis = new Date(issued.getFullYear(), issued.getMonth() - 1, 15);
  } else if (cadence === 'quarterly') {
    basis = new Date(issued.getFullYear(), issued.getMonth() - 3, 15);
  } else {
    basis = new Date(issued.getTime() - 7 * 86400000);
  }
}

const period = cadence === 'monthly' ? monthKey(basis)
             : cadence === 'quarterly' ? quarterKey(basis)
             : weekKey(basis);

return [{ json: {
  matched: true,
  reason: '',
  supplier: clean(row.supplier),            // the register's spelling, so the chase index lines up
  read_supplier: readSupplier,
  invoice_number: clean(doc.invoice_number),
  issue_date: issued ? issued.toISOString().slice(0, 10) : '',
  period: period,
  period_inferred: inferred,
  received_at: new Date().toISOString(),
} }];
